# bash completion for bump-version
# Generated by `make completions` from the argparse parser; do not edit.

_bump_version() {
    local cur=${COMP_WORDS[COMP_CWORD]} prev=${COMP_WORDS[COMP_CWORD-1]}
    local cmd="" i

    # A value-taking option's argument is free text: offer nothing.
    case $prev in
        -m|--message|--prefix) return 0 ;;
    esac

    # The subcommand, if one was typed, skipping option values.
    for ((i = 1; i < COMP_CWORD; i++)); do
        case ${COMP_WORDS[i]} in
            -m|--message|--prefix) ((i++)) ;;
            major|minor|patch|current|dynamic-pyproject) cmd=${COMP_WORDS[i]}; break ;;
        esac
    done

    local words
    case $cmd in
        "") words="-h --help -s --sync -p --push -n --dry-run -m --message --prefix -y --yes -v --version" ;;
        major) words="-h --help -s --sync -p --push -n --dry-run -m --message --prefix -y --yes" ;;
        minor) words="-h --help -s --sync -p --push -n --dry-run -m --message --prefix -y --yes" ;;
        patch) words="-h --help -s --sync -p --push -n --dry-run -m --message --prefix -y --yes" ;;
        current) words="-h --help -s --sync -p --push -n --dry-run -m --message --prefix -y --yes" ;;
        dynamic-pyproject) words="-h --help -n --dry-run -y --yes --prefix" ;;
    esac
    if [[ -z $cmd && $cur != -* ]]; then
        words="major minor patch current dynamic-pyproject"
    fi
    mapfile -t COMPREPLY < <(compgen -W "$words" -- "$cur")
}

complete -F _bump_version bump-version
